// Your brand: the names an answer may use, and your domain (its subdomains count too).
const names = ['Reduck'];
const domain = 'reduck.ai';

// The questions your buyers ask, in their own words.
const questions = [
  'What is the best tool to automate LinkedIn from n8n?',
  'How can an AI agent use a website that has no API?',
  'What are the alternatives to Apify for scraping LinkedIn?',
];

return questions.map((question) => ({ json: { question, names, domain } }));

const { question, names, domain } = $('Your brand and questions').item.json;
const answer = $json.result?.answer ?? '';
const references = $json.result?.references ?? [];
// The progress lines ChatGPT showed ("Searching the web"): none means it answered from memory.
const searched = ($json.result?.activity ?? []).length > 0 || references.length > 0;

// The Code sandbox has no URL global, so the host is read with a pattern.
const hostOf = (url) => /^https?:\/\/(?:www\.)?([^/?#:]+)/i.exec(url ?? '')?.[1]?.toLowerCase();
// Anchored on a dot, so notreduck.ai is not reduck.ai.
const ours = (host) => host === domain || host.endsWith(`.${domain}`);
const cited = [...new Set(references.map((r) => hostOf(r.url)).filter(Boolean))];
const named = names.some((n) => answer.toLowerCase().includes(n.toLowerCase()));

const verdict = $json.error
  ? 'failed'
  : cited.some(ours)
    ? 'cited'
    : named
      ? 'named'
      : searched
        ? 'absent'
        : 'no search';

return {
  json: {
    date: new Date().toISOString().slice(0, 10),
    question,
    verdict,
    cited_domains: cited.filter((h) => !ours(h)).join(', '),
    answer: $json.error ?? answer,
    run: $json.id ? `https://reduck.ai/runs/${$json.id}` : '',
  },
};
